import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    expected_width = 6
    columns = None
    rows = []

    def record_lines(first_line, continuation):
        yield first_line
        yield from continuation

    for line in stream:
        if not line.strip():
            continue

        left = line.lstrip()
        if left.startswith("#"):
            if columns is None:
                candidate = next(
                    csv.reader([left[1:].lstrip()], skipinitialspace=True),
                    [],
                )
                if len(candidate) == expected_width:
                    columns = [field.strip() for field in candidate]
            continue

        # Let the CSV reader consume continuation lines before testing for
        # another comment or blank line.
        record = next(csv.reader(
            record_lines(line, stream),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=True,
        ))

        if columns is None:
            if len(record) == expected_width:
                columns = [field.strip() for field in record]
        else:
            rows.append(record)

    if columns is None:
        return {"columns": [], "rows": []}

    width = max(len(columns), max((len(row) for row in rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
